using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BlockPavingLayout{struct Seg{public Vector2 a,b;public Seg(Vector2 x,Vector2 y){a=x;b=y;}}static BlockPavingLayout(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("BlockPavingLayout.request"))return;File.Delete("BlockPavingLayout.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BlockPavingLayout.txt",e.ToString());Debug.LogException(e);}}
static string Key(Vector2 p)=>Mathf.RoundToInt(p.x*50)+","+Mathf.RoundToInt(p.y*50);static string Key(Seg s){string a=Key(s.a),b=Key(s.b);return string.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;}static bool Join(Seg a,Seg b,out Seg c){c=new Seg();if(Vector2.Distance(a.a,b.a)<.04)c=new Seg(a.b,b.b);else if(Vector2.Distance(a.a,b.b)<.04)c=new Seg(a.b,b.a);else if(Vector2.Distance(a.b,b.a)<.04)c=new Seg(a.a,b.b);else if(Vector2.Distance(a.b,b.b)<.04)c=new Seg(a.a,b.a);else return false;return true;}
static List<Seg> Simplify(List<Seg> s,bool walls=false){bool changed=true;while(changed){changed=false;for(int i=0;i<s.Count&&!changed;i++)for(int j=i+1;j<s.Count;j++){Seg c;var dir=(s[i].b-s[i].a).normalized;float len=Vector2.Distance(s[i].a,s[i].b);float t0=Vector2.Dot(s[j].a-s[i].a,dir),t1=Vector2.Dot(s[j].b-s[i].a,dir);float off=Mathf.Abs((s[j].a.x-s[i].a.x)*dir.y-(s[j].a.y-s[i].a.y)*dir.x);if(walls&&off<.18f&&Mathf.Abs(Vector2.Dot(dir,(s[j].b-s[j].a).normalized))>.9995f&&Mathf.Min(t0,t1)<len+1.2f&&Mathf.Max(t0,t1)>-1.2f){var origin=s[i].a;s[i]=new Seg(origin+dir*Mathf.Min(0,Mathf.Min(t0,t1)),origin+dir*Mathf.Max(len,Mathf.Max(t0,t1)));s.RemoveAt(j);changed=true;break;}if(Join(s[i],s[j],out c)&&Mathf.Abs(Vector2.Dot((s[i].b-s[i].a).normalized,(s[j].b-s[j].a).normalized))>.9995){s[i]=c;s.RemoveAt(j);changed=true;break;}}}while(s.Count>48){float best=float.MaxValue;int ai=-1,bi=-1;Seg merged=new Seg();for(int i=0;i<s.Count;i++)for(int j=i+1;j<s.Count;j++){Seg c;if(!Join(s[i],s[j],out c))continue;float cost=(1-Mathf.Abs(Vector2.Dot((s[i].b-s[i].a).normalized,(s[j].b-s[j].a).normalized)))*Mathf.Min(Vector2.Distance(s[i].a,s[i].b),Vector2.Distance(s[j].a,s[j].b));if(cost<best){best=cost;ai=i;bi=j;merged=c;}}if(ai<0){if(walls)return s.OrderByDescending(e=>Vector2.Distance(e.a,e.b)).Take(48).ToList();File.WriteAllLines("FinalEnvironmentRoadReview/BlockPavingSegments.txt",s.Select(e=>e.a+" to "+e.b));throw new Exception("Disconnected contours exceed mapping capacity count="+s.Count);}s[ai]=merged;s.RemoveAt(bi);}return s;}
static void Read(Renderer r,out Vector3[] p,out int[] ids){var f=r.GetComponent<MeshFilter>();var d=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{f.sharedMesh});p=((Vector3[])d.GetType().GetField("p").GetValue(d)).Select(f.transform.TransformPoint).ToArray();ids=(int[])d.GetType().GetField("ids").GetValue(d);}
static bool At(Vector2 q,Vector3[] ps,int[] ids){for(int k=0;k<ids.Length;k+=3){var a=ps[ids[k]];var b=ps[ids[k+1]]-a;var c=ps[ids[k+2]]-a;float det=b.x*c.z-b.z*c.x;if(Mathf.Abs(det)<.0001)continue;float u=((q.x-a.x)*c.z-(q.y-a.z)*c.x)/det,v=(b.x*(q.y-a.z)-b.z*(q.x-a.x))/det;if(u>=0&&v>=0&&u+v<=1)return true;}return false;}
static Vector2 XZ(Vector3 p)=>new Vector2(p.x,p.z);static bool Near(Bounds a,Bounds b)=>Mathf.Abs(a.center.x-b.center.x)<a.extents.x+b.extents.x+3&&Mathf.Abs(a.center.z-b.center.z)<a.extents.z+b.extents.z+3;
static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roots=sc.GetRootGameObjects();var host=roots.Single(g=>g.name=="Track Roads");var map=host.GetComponent<CityGroundTextureLayout>();var rs=roots.SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh).ToArray();string prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(host),bk="FinalEnvironmentRoadBackup/BeforeBlockPaving/";foreach(var f in new[]{sc.path,prefab})if(!File.Exists(bk+Path.GetFileName(f)))File.Copy(f,bk+Path.GetFileName(f));if(ShaderUtil.ShaderHasError(map.plots[0].renderer.sharedMaterial.shader))throw new Exception("Ground shader error");var log=new List<string>();foreach(string name in new[]{"polySurface737","polySurface102"}){var p=map.plots.Single(t=>t.renderer.name==name);Vector3[] ps;int[] ids;Read(p.renderer,out ps,out ids);var ed=new List<Seg>();for(int k=0;k<ids.Length;k+=3)for(int j=0;j<3;j++){var s=new Seg(XZ(ps[ids[k+j]]),XZ(ps[ids[k+(j+1)%3]]));if(Vector2.Distance(s.a,s.b)>.1)ed.Add(s);}var outline=Simplify(ed.GroupBy(Key).Where(g=>g.Count()%2==1).Select(g=>g.First()).ToList());var facades=new List<Seg>();foreach(var b in rs.Where(r=>r.sharedMaterial&&r.sharedMaterial.name.StartsWith("Building")&&r.bounds.size.y>4&&r.bounds.min.y<31&&Near(r.bounds,p.renderer.bounds))){Vector3[] bp;int[] bi;Read(b,out bp,out bi);float baseY=bp.Min(v=>v.y);for(int k=0;k<bi.Length;k+=3){var a=bp[bi[k]];var bb=bp[bi[k+1]];var c=bp[bi[k+2]];if(Mathf.Abs(Vector3.Cross(bb-a,c-a).normalized.y)>.25)continue;for(int j=0;j<3;j++){var aa=bp[bi[k+j]];var cc=bp[bi[k+(j+1)%3]];if(aa.y<baseY+.35&&cc.y<baseY+.35&&Vector2.Distance(XZ(aa),XZ(cc))>1)facades.Add(new Seg(XZ(aa),XZ(cc)));}}}facades=Simplify(facades.GroupBy(Key).Select(g=>g.First()).ToList(),true);var treeList=new List<MeshRenderer>();foreach(var r in rs.Where(r=>r.name.StartsWith("Grass path")||r.name.StartsWith("Object001")).OrderBy(r=>r.name.StartsWith("Grass path")?0:1)){var q=XZ(r.bounds.center);if(!At(q,ps,ids)&&!new[]{new Vector2(2,0),new Vector2(-2,0),new Vector2(0,2),new Vector2(0,-2)}.Any(off=>At(q+off,ps,ids)))continue;if(treeList.Any(t=>Vector2.Distance(XZ(t.bounds.center),q)<2))continue;treeList.Add(r);}var trees=treeList.OrderByDescending(t=>t.bounds.center.z).ToArray();if(trees.Length>12)throw new Exception("Too many existing tree beds on "+name);p.data.x=6;p.data.z=trees.Length;p.data.w=outline.Count;p.feature0=new Vector4(0,0,0,facades.Count);p.feature1=new Vector4(-10000,0,0,0);p.outline=new Vector4[48];p.facades=new Vector4[48];for(int k=0;k<outline.Count;k++)p.outline[k]=new Vector4(outline[k].a.x,outline[k].a.y,outline[k].b.x,outline[k].b.y);for(int k=0;k<facades.Count;k++)p.facades[k]=new Vector4(facades[k].a.x,facades[k].a.y,facades[k].b.x,facades[k].b.y);for(int k=0;k<trees.Length;k++){var c=trees[k].bounds.center;p.patches[k]=new Vector4(c.x,c.z,2.7f,3.2f);p.modes[k]=new Vector4(3,0,1,0);}if(trees.Length>0){var t=XZ(trees[0].bounds.center);float best=float.MaxValue;Vector2 target=t;foreach(var seg in facades){var d=seg.b-seg.a;var q=seg.a+d*Mathf.Clamp01(Vector2.Dot(t-seg.a,d)/Mathf.Max(d.sqrMagnitude,.001f));float dist=Vector2.Distance(t,q);if(dist<best){best=dist;target=q;}}var outward=(t-target).normalized;if(outward.sqrMagnitude<.1)outward=(t-new Vector2(p.rect.x,p.rect.y)).normalized;var side=new Vector2(-outward.y,outward.x);var start=t+side*5+outward*10;var end=target+side*5;p.feature1=new Vector4(start.x,start.y,end.x,end.y);}File.WriteAllLines("FinalEnvironmentRoadReview/BlockTrees-"+name+".txt",rs.Where(r=>(r.name.StartsWith("Grass path")||r.name.StartsWith("Object001"))&&Near(r.bounds,p.renderer.bounds)).Select(r=>r.name+" "+r.bounds.center));log.Add(name+": boundary segments="+outline.Count+" facade segments="+facades.Count+" existing tree beds="+trees.Length+" bounds="+p.renderer.bounds);}
map.Apply();EditorUtility.SetDirty(map);PrefabUtility.RecordPrefabInstancePropertyModifications(map);PrefabUtility.ApplyObjectOverride(map,prefab,InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);var ctrl=roots.SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.ApplyDay();map.Apply();var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static);foreach(string name in new[]{"polySurface737","polySurface102"}){var p=map.plots.Single(t=>t.renderer.name==name);var c=p.renderer.bounds.center;float span=Mathf.Max(p.rect.z,p.rect.w);var tree=p.patches[0];var tc=new Vector3(tree.x,c.y,tree.y);var outward=(tc-c).normalized;outward.y=0;if(outward.sqrMagnitude<.1)outward=Vector3.right;cap.Invoke(null,new object[]{sc,tc+outward*24+Vector3.up*15,tc-outward*4+Vector3.up*2,"Block-Paving-"+name+"-Overview"});if(name=="polySurface737")cap.Invoke(null,new object[]{sc,new Vector3(800,72,495),new Vector3(755,35,466),"Block-Paving-polySurface737-Front-Plaza"});cap.Invoke(null,new object[]{sc,c+new Vector3(1,span*2.05f,.5f),c,"Block-Paving-"+name+"-Top"});cap.Invoke(null,new object[]{sc,c+new Vector3(span*.85f,span*.65f,span*.65f),c+Vector3.up*4,"Block-Paving-"+name+"-Rear"});}}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();map.Apply();}EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/BlockPavingLayout.txt","SUCCESS full plots updated, all sides and back. Contours read from original geometry; no mesh or UV editing. Existing shared material and atlas reused; no new texture/material assets. Scene and prefab saved.\n"+string.Join("\n",log));File.WriteAllText("CityGroundTextureVerify.request","run");}}